def questions():
    out = []
    names = {c: n for c, n, *_ in DOMAINS}
    links = {c: (u, l) for c, _, _, u, l in DOMAINS}
    for i, (dom, diff, stem, opts, ans, hint, why, sid) in enumerate(Q, 1):
        ans = ans if isinstance(ans, list) else [ans]
        out.append({"qid": f"csa-q{i:03d}", "type": "multi" if len(ans) > 1 else "single", "stem": stem, "choose": len(ans) if len(ans) > 1 else None,
                    "options": [{"id": "abcd"[j], "text": t, "why": why[j]} for j, t in enumerate(opts)], "correct": ["abcd"[j] for j in ans],
                    "domain": names[dom], "difficulty": diff, "hint": hint, "ref_url": links[dom][0], "ref_label": links[dom][1],
                    "tags": ["csa-v1", "312-39", dom.lower()], "scenario_id": sid})
    return out
